1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"reflect"
12		"sort"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked = "未检查"
18		StatusPass      = "通过"
19		StatusDefect    = "发现缺陷"
20	)
21	
22	// ReportArtifact identifies the audited artifact by name and content hash.
23	type ReportArtifact struct {
24		Name string `json:"name"`
25		Hash string `json:"hash"`
26	}
27	
28	// ReportRule is one rule together with the invariant check result.
29	type ReportRule struct {
30		ID          string `json:"id"`
31		Kind        string `json:"kind"`
32		Severity    string `json:"severity"`
33		Invariant   string `json:"invariant"`
34		RequiresABI bool   `json:"requiresABI"`
35		Version     string `json:"version"`
36		Status      string `json:"status"`
37	}
38	
39	// ReportFinding binds a defect to its artifact, rule, version and evidence.
40	type ReportFinding struct {
41		ArtifactHash string `json:"artifactHash"`
42		RuleID       string `json:"ruleId"`
43		Version      string `json:"version"`
44		Severity     string `json:"severity"`
45		Invariant    string `json:"invariant"`
46		Evidence     string `json:"evidence"`
47	}
48	
49	// Report is the persisted audit result.
50	type Report struct {
51		ReportID string          `json:"reportId"`
52		Artifact ReportArtifact  `json:"artifact"`
53		Rules    []ReportRule    `json:"rules"`
54		Findings []ReportFinding `json:"findings"`
55	}
56	
57	// wireArtifact is the JSON shape of an artifact in an audit submission.
58	type wireArtifact struct {
59		Name     string `json:"name"`
60		ABI      string `json:"abi"`
61		Bytecode string `json:"bytecode"`
62		Source   string `json:"source"`
63	}
64	
65	// wireRule is the JSON shape of a rule in an audit submission.
66	type wireRule struct {
67		ID          string `json:"id"`
68		Kind        string `json:"kind"`
69		Severity    string `json:"severity"`
70		Invariant   string `json:"invariant"`
71		RequiresABI bool   `json:"requiresABI"`
72		Version     string `json:"version"`
73	}
74	
75	// wireInput is the JSON object accepted by the audit command.
76	type wireInput struct {
77		Artifact   wireArtifact               `json:"artifact"`
78		Rules      []wireRule                 `json:"rules"`
79		Invariants map[string]json.RawMessage `json:"invariants"`
80	}
81	
82	// ParseAuditInput decodes an audit submission JSON object into domain values.
83	// Invariant values must be JSON booleans; any other type is an error.
84	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, error) {
85		var in wireInput
86		if err := json.Unmarshal(data, &in); err != nil {
87			return Artifact{}, nil, nil, errInvalid("invalid JSON: " + err.Error())
88		}
89		invariants := make(map[string]bool, len(in.Invariants))
90		for key, raw := range in.Invariants {
91			var holds bool
92			if err := json.Unmarshal(raw, &holds); err != nil {
93				return Artifact{}, nil, nil, errInvalid("invariant " + key + " must be a boolean")
94			}
95			invariants[key] = holds
96		}
97		artifact := Artifact{
98			Name:     in.Artifact.Name,
99			ABI:      in.Artifact.ABI,
100			Bytecode: in.Artifact.Bytecode,
101			Source:   in.Artifact.Source,
102		}
103		rules := make([]Rule, 0, len(in.Rules))
104		for _, wr := range in.Rules {
105			rules = append(rules, Rule{
106				ID:          wr.ID,
107				Kind:        wr.Kind,
108				Severity:    wr.Severity,
109				Invariant:   wr.Invariant,
110				RequiresABI: wr.RequiresABI,
111				Version:     wr.Version,
112			})
113		}
114		return artifact, rules, invariants, nil
115	}
116	
117	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
118	// bytecode and source strings contribute; field boundaries are explicit
119	// (length-prefixed) so that different splits never collide. The source is
120	// hashed as a field value, never read from disk, and the name does not
121	// participate.
122	func ArtifactHash(a Artifact) string {
123		h := sha256.New()
124		h.Write([]byte("contractsentinel-artifact-v1\n"))
125		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
126			fmt.Fprintf(h, "%d\n", len(field))
127			h.Write([]byte(field))
128		}
129		sum := h.Sum(nil)
130		return hex.EncodeToString(sum)
131	}
132	
133	// BuildReport evaluates rules against the artifact and invariant values and
134	// produces the report to persist. Insufficient inputs (missing ABI for a rule
135	// that requires it, missing bytecode for a symbolic rule) fail the whole
136	// submission and are never recorded as defects.
137	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool) (Report, error) {
138		if artifact.Name == "" {
139			return Report{}, errInvalid("artifact name is required")
140		}
141		seen := make(map[string]bool, len(rules))
142		for _, rule := range rules {
143			if rule.ID == "" {
144				return Report{}, errInvalid("rule id is required")
145			}
146			if rule.Version == "" {
147				return Report{}, errInvalid("rule " + rule.ID + " version is required")
148			}
149			if seen[rule.ID] {
150				return Report{}, errInvalid("duplicate rule id " + rule.ID)
151			}
152			seen[rule.ID] = true
153			if rule.RequiresABI && artifact.ABI == "" {
154				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
155			}
156			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
157				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
158			}
159		}
160		hash := ArtifactHash(artifact)
161		report := Report{
162			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
163			Rules:    []ReportRule{},
164			Findings: []ReportFinding{},
165		}
166		for _, rule := range rules {
167			status := StatusUnchecked
168			if holds, checked := invariants[rule.Invariant]; checked {
169				if holds {
170					status = StatusPass
171				} else {
172					status = StatusDefect
173				}
174			}
175			report.Rules = append(report.Rules, ReportRule{
176				ID:          rule.ID,
177				Kind:        rule.Kind,
178				Severity:    rule.Severity,
179				Invariant:   rule.Invariant,
180				RequiresABI: rule.RequiresABI,
181				Version:     rule.Version,
182				Status:      status,
183			})
184			if status == StatusDefect {
185				report.Findings = append(report.Findings, ReportFinding{
186					ArtifactHash: hash,
187					RuleID:       rule.ID,
188					Version:      rule.Version,
189					Severity:     rule.Severity,
190					Invariant:    rule.Invariant,
191					Evidence:     "invariant " + rule.Invariant + " does not hold",
192				})
193			}
194		}
195		report.ReportID = ReportID(report)
196		return report, nil
197	}
198	
199	// canonicalRule is the order-independent view of a rule used for the id.
200	type canonicalRule struct {
201		ID          string `json:"id"`
202		Kind        string `json:"kind"`
203		Severity    string `json:"severity"`
204		Invariant   string `json:"invariant"`
205		RequiresABI bool   `json:"requiresABI"`
206		Version     string `json:"version"`
207		Status      string `json:"status"`
208	}
209	
210	// canonicalFinding is the order-independent view of a finding used for the id.
211	type canonicalFinding struct {
212		ArtifactHash string `json:"artifactHash"`
213		RuleID       string `json:"ruleId"`
214		Version      string `json:"version"`
215		Severity     string `json:"severity"`
216		Invariant    string `json:"invariant"`
217		Evidence     string `json:"evidence"`
218	}
219	
220	// canonicalReport is the deterministic content a report id is computed from.
221	type canonicalReport struct {
222		ArtifactHash string             `json:"artifactHash"`
223		Name         string             `json:"name"`
224		Rules        []canonicalRule    `json:"rules"`
225		Findings     []canonicalFinding `json:"findings"`
226	}
227	
228	// canonicalize renders a report into its order-independent form.
229	func canonicalize(report Report) canonicalReport {
230		cr := canonicalReport{
231			ArtifactHash: report.Artifact.Hash,
232			Name:         report.Artifact.Name,
233		}
234		for _, rule := range report.Rules {
235			cr.Rules = append(cr.Rules, canonicalRule{
236				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
237				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
238				Version: rule.Version, Status: rule.Status,
239			})
240		}
241		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
242		for _, finding := range report.Findings {
243			cr.Findings = append(cr.Findings, canonicalFinding{
244				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
245				Version: finding.Version, Severity: finding.Severity,
246				Invariant: finding.Invariant, Evidence: finding.Evidence,
247			})
248		}
249		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
250		return cr
251	}
252	
253	// ReportID returns the content-addressed identifier of a report. The id binds
254	// the artifact hash, name, complete rule definitions, the invariant value
255	// used by each rule (unchecked and explicit pass are distinct), and the
256	// findings. Rule order, invariant key order and unrelated invariant keys do
257	// not influence it.
258	func ReportID(r Report) string {
259		data, err := json.Marshal(canonicalize(r))
260		if err != nil {
261			panic(err) // canonical values are all strings and bools
262		}
263		sum := sha256.Sum256(data)
264		return hex.EncodeToString(sum[:])
265	}
266	
267	// expectedFindings rebuilds the findings that match a report's rules.
268	func expectedFindings(r Report) []ReportFinding {
269		var out []ReportFinding
270		for _, rule := range r.Rules {
271			if rule.Status == StatusDefect {
272				out = append(out, ReportFinding{
273					ArtifactHash: r.Artifact.Hash,
274					RuleID:       rule.ID,
275					Version:      rule.Version,
276					Severity:     rule.Severity,
277					Invariant:    rule.Invariant,
278					Evidence:     "invariant " + rule.Invariant + " does not hold",
279				})
280			}
281		}
282		return out
283	}
284	
285	// sameFindings compares two finding sets independently of order; nil and empty
286	// slices are treated as equal.
287	func sameFindings(a, b []ReportFinding) bool {
288		if len(a) == 0 && len(b) == 0 {
289			return true
290		}
291		ac := append([]ReportFinding(nil), a...)
292		bc := append([]ReportFinding(nil), b...)
293		sort.Slice(ac, func(i, j int) bool { return ac[i].RuleID < ac[j].RuleID })
294		sort.Slice(bc, func(i, j int) bool { return bc[i].RuleID < bc[j].RuleID })
295		return reflect.DeepEqual(ac, bc)
296	}
297	
298	// verifyReportBytes parses stored bytes and checks they match the id and that
299	// the findings are consistent with the rules.
300	func verifyReportBytes(data []byte, id string) error {
301		var r Report
302		if err := json.Unmarshal(data, &r); err != nil {
303			return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
304		}
305		if r.ReportID != id {
306			return errCorrupt("report id " + r.ReportID + " does not match stored id " + id)
307		}
308		if ReportID(r) != id {
309			return errCorrupt("report content does not match id " + id)
310		}
311		if !sameFindings(expectedFindings(r), r.Findings) {
312			return errCorrupt("report findings do not match rules for id " + id)
313		}
314		return nil
315	}
316	
317	// SaveReport persists a report under the store directory. The store is safe
318	// for concurrent writers: identical reports share one file and all
319	// submissions succeed, different reports never overwrite each other, and
320	// readers only ever observe complete files. A pre-existing file with the same
321	// id must carry the same report; a corrupted archive makes the submission
322	// fail while keeping the original file.
323	func SaveReport(dir string, r Report) error {
324		if r.ReportID == "" {
325			return errInvalid("report id is required")
326		}
327		if err := os.MkdirAll(dir, 0o755); err != nil {
328			return err
329		}
330		finalPath := filepath.Join(dir, r.ReportID+".json")
331		if existing, err := os.ReadFile(finalPath); err == nil {
332			if err := verifyReportBytes(existing, r.ReportID); err != nil {
333				return err
334			}
335			return nil
336		} else if !os.IsNotExist(err) {
337			return err
338		}
339		data, err := json.Marshal(r)
340		if err != nil {
341			return err
342		}
343		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
344		if err != nil {
345			return err
346		}
347		tmpPath := tmp.Name()
348		cleanup := func() { os.Remove(tmpPath) }
349		if _, err := tmp.Write(data); err != nil {
350			tmp.Close()
351			cleanup()
352			return err
353		}
354		if err := tmp.Sync(); err != nil {
355			tmp.Close()
356			cleanup()
357			return err
358		}
359		if err := tmp.Close(); err != nil {
360			cleanup()
361			return err
362		}
363		if err := os.Rename(tmpPath, finalPath); err != nil {
364			cleanup()
365			if existing, readErr := os.ReadFile(finalPath); readErr == nil {
366				if verifyErr := verifyReportBytes(existing, r.ReportID); verifyErr != nil {
367					return verifyErr
368				}
369				return nil
370			}
371			return err
372		}
373		return nil
374	}
375	
376	// LoadReport reads and verifies a report by id. Missing, corrupted or tampered
377	// archives produce a clear error.
378	func LoadReport(dir, id string) (Report, error) {
379		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
380		if err != nil {
381			if os.IsNotExist(err) {
382				return Report{}, errNotFound("report " + id + " not found")
383			}
384			return Report{}, err
385		}
386		var r Report
387		if err := json.Unmarshal(data, &r); err != nil {
388			return Report{}, errCorrupt("invalid JSON in report " + id)
389		}
390		if r.ReportID != id {
391			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
392		}
393		if ReportID(r) != id {
394			return Report{}, errCorrupt("report content does not match id " + id)
395		}
396		if !sameFindings(expectedFindings(r), r.Findings) {
397			return Report{}, errCorrupt("report findings do not match rules for id " + id)
398		}
399		return r, nil
400	}
401	
402	type errNotFound string
403	
404	func (e errNotFound) Error() string { return string(e) }
405	
406	type errCorrupt string
407	
408	func (e errCorrupt) Error() string { return string(e) }
409

