199	// BuildReportWithChecks is BuildReport with externally imported check
200	// results. Each check must target a known rule, match this submission's
201	// artifact hash and the rule's current version, carry a known status, and
202	// explain 发现缺陷/工具缺失/超时 with non-whitespace text. A rule that
203	// receives a check record must not also receive its invariant as a boolean
204	// in the same submission. Any violation rejects the whole submission.
205	func BuildReportWithChecks(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
206		if artifact.Name == "" {
207			return Report{}, errInvalid("artifact name is required")
208		}
209		ruleByID := make(map[string]Rule, len(rules))
210		seen := make(map[string]bool, len(rules))
211		for _, rule := range rules {
212			if rule.ID == "" {
213				return Report{}, errInvalid("rule id is required")
214			}
215			if rule.Version == "" {
216				return Report{}, errInvalid("rule " + rule.ID + " version is required")
217			}
218			if seen[rule.ID] {
219				return Report{}, errInvalid("duplicate rule id " + rule.ID)
220			}
221			seen[rule.ID] = true
222			if rule.RequiresABI && artifact.ABI == "" {
223				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
224			}
225			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
226				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
227			}
228			ruleByID[rule.ID] = rule
229		}
230		hash := ArtifactHash(artifact)
231		checkByRule := make(map[string]CheckRecord, len(checks))
232		for _, check := range checks {
233			rule, ok := ruleByID[check.RuleID]
234			if !ok {
235				return Report{}, errInvalid("check targets unknown rule " + check.RuleID)
236			}
237			if _, dup := checkByRule[check.RuleID]; dup {
238				return Report{}, errInvalid("duplicate check record for rule " + check.RuleID)
239			}
240			if !validCheckStatus(check.Status) {
241				return Report{}, errInvalid("check for rule " + check.RuleID + " has unknown status " + check.Status)
242			}
243			if noteRequired(check.Status) && strings.TrimSpace(check.Note) == "" {
244				return Report{}, errInvalid("check for rule " + check.RuleID + " with status " + check.Status + " requires a non-empty note")
245			}
246			if check.ArtifactHash != hash {
247				return Report{}, errInvalid("check for rule " + check.RuleID + " artifact hash " + check.ArtifactHash + " does not match submission hash " + hash)
248			}
249			if check.RuleVersion != rule.Version {
250				return Report{}, errInvalid("check for rule " + check.RuleID + " rule version " + check.RuleVersion + " does not match version " + rule.Version)
251			}
252			if _, hasBool := invariants[rule.Invariant]; hasBool {
253				return Report{}, errInvalid("rule " + check.RuleID + " received both a check record and invariant " + rule.Invariant + " boolean")
254			}
255			checkByRule[check.RuleID] = check
256		}
