266				status = check.Status
267				note = check.Note
268			} else if holds, checked := invariants[rule.Invariant]; checked {
269				if holds {
270					status = StatusPass
271				} else {
272					status = StatusDefect
273				}
274			}
275			report.Rules = append(report.Rules, ReportRule{
